#!/usr/bin/env python3

# Manipulates the ribbons that make up the sleeves for this costume.
#
# The intended usage for this script is to redirect its streams, as it will consume all input to
# stdin until EOF:
# $ python3 sleeves.py <posecode.txt >finalcode.txt                # Unix shell, using files
# > Get-Content posecode.txt | python3 sleeves.py > finalcode.txt  # PowerShell, using files
# $ pbpaste | python3 sleeves.py | pbcopy                          # macOS, using clipboard
#
# This works by pasting in a code that hides all of them behind her arms, and then pasting codes for
# the ribbons that need to be "shown" over top to restore their original appearance from the
# wardrobe code, or by doing so for two positions with the mirroring setting changed.
#
# We can do this because Kisekae accepts ribbon codes placed anywhere in the code, including at the
# end, and it will happily replace any ribbon that appears twice in the code with whichever one
# comes later.


from argparse import ArgumentParser
import re
import sys


def set_side(setting: int):
    def set_mirror(match: re.Match):
        first = match.group(1)
        return f'{first}{setting}.'
    return set_mirror


