xm_pattern = r'(xm(\d{2,3})\.\d{1,3}\.(?:[0-9a-fA-F]{1,6}\.){3})(\d)\.'

arg_parser = ArgumentParser(description="Add the big sleeves to a pose code for Kyouko's jiangshi "
                                        "outfit")
arg_parser.add_argument("right", choices=codes.keys(),
                        help="Position for Kyouko's right arm (stage left)")
arg_parser.add_argument("left", choices=codes.keys(),
                        help="Position for Kyouko's left arm (stage right)")
args = arg_parser.parse_args(sys.argv[1:])

content = sys.stdin.read()

content += base
if args.left == args.right:
    content += codes[args.left]
else:
    content += re.sub(xm_pattern, set_side(2), codes[args.right])
    content += re.sub(xm_pattern, set_side(1), codes[args.left])

sys.stdout.write(content)
